mapper.select:
SELECT Board_SKIN_COMM_ID, BOARD_SKIN_ID,unickname,ucontent,reip,bcdate, row_num FROM (
SELECT Board_SKIN_COMM_ID, BOARD_SKIN_ID,unickname,ucontent,reip,bcdate, ROW_NUMBER()
OVER(ORDER BY BOARD_SKIN_COMM_ID desc) AS row_num FROM Board_SKIN_COMM where BOARD_SKIN_ID=#{board_skin_id}
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE BOARD_SKIN
SET comm_count = comm_count + 1
WHERE board_skin_id = #{board_skin_id}

UPDATE BOARD_SKIN
SET comm_count = comm_count - 1
WHERE board_skin_id = #{board_skin_id}
